<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,reactive,ref } from 'vue'
import { useRouter } from 'vue-router'
import auth from '@/plugins/auth'
import NxrPageHeader from '@/components/NxrWorkspace/PageHeader.vue'
import { getWalletRecharges,getWalletTransactions,reviewWalletRecharge } from '@/api/nxr/merchantWallet'
import { getPartner,listPartners,provisionPartner,requestPartnerRecharge,setPartnerOperatorState,updatePartner,type PartnerDetail,type PartnerOperator,type PartnerPage,type PartnerProfileInput,type PartnerRecharge,type PartnerSummary } from '@/api/nxr/partners'
import { agentDateLabel,agentStatusLabel,formatMoney } from '../agent-workbench/lib/agentWorkbench'
defineOptions({name:'NxrPartners'})
const router=useRouter()
const canManage=auth.hasPermiAnd(['nxr:partner:manage','nxr:customer:manage'])
const canOpen=canManage&&auth.hasPermi('system:user:add')
const canFinance=auth.hasPermi('nxr:customer:finance')
const canRecharge=canFinance&&auth.hasPermi('nxr:partner:manage')
const canWorkbench=auth.hasPermiOr(['nxr:agent:workbench','nxr:agent:manage'])
const canNxrOrders=auth.hasPermi('nxr:order:list')
const canManageOperators=auth.hasPermi('nxr:agent:manage')
const currencies=['USD','CNY','EUR','GBP','HKD','JPY','CAD','AUD','SGD']
const emptyPage=<T,>():PartnerPage<T>=>({items:[],page:1,pageSize:20,total:0})
const listing=ref(emptyPage<PartnerSummary>()),loading=ref(false),busy=ref(false),error=ref(''),success=ref('')
const query=reactive({query:'',active:'' as boolean|'',currencyCode:'USD'})
const detail=ref<PartnerDetail|null>(null),detailOpen=ref(false),detailLoading=ref(false),detailTab=ref('overview'),editingProfile=ref(false)
const profile=ref<PartnerProfileInput>({displayName:'',email:'',mobile:'',companyName:'',contactName:'',active:true})
const accountOpen=ref(false),accountPartner=ref<PartnerSummary|null>(null)
const blankAccount=()=>({companyName:'',contactName:'',displayName:'',email:'',mobile:'',userName:'',nickName:'',password:''})
const account=ref(blankAccount())
const rechargeOpen=ref(false),recharge=reactive({currencyCode:'USD',amount:'',providerCode:'bank_transfer',payerReference:'',proofReference:''})
const recharges=ref(emptyPage<PartnerRecharge>()),rechargeStatus=ref('pending'),transactions=ref(emptyPage<{id:number;directionCode:string;amount:number;balanceAfter:number;note:string;createdAt:string}>()),transactionCurrency=ref('USD')
const reviewOpen=ref(false),review=reactive({item:null as PartnerRecharge|null,approved:true,providerTransactionId:'',note:''})
const financeVisible=computed(()=>Boolean(canFinance&&detail.value?.financeVisible))
const attempts=new Map<string,{fingerprint:string;key:string}>()
let listGeneration=0,detailGeneration=0,financeGeneration=0,active=true
function message(e:unknown){return e instanceof Error?e.message:'操作未完成，请重试。'}
function profileFor(row:PartnerSummary):PartnerProfileInput{return {displayName:row.displayName,email:row.email,mobile:row.mobile||'',companyName:row.companyName,contactName:row.contactName,active:row.active}}
async function load(page=1){const current=++listGeneration;loading.value=true;error.value='';try{const value=await listPartners({page,pageSize:20,...query,active:query.active===''?undefined:query.active});if(active&&current===listGeneration)listing.value=value}catch(e){if(active&&current===listGeneration)error.value=message(e)}finally{if(active&&current===listGeneration)loading.value=false}}
async function openPartner(id:number){
  if(busy.value)return
  const current=++detailGeneration;financeGeneration++;detail.value=null;detailOpen.value=true;detailLoading.value=true;detailTab.value='overview';editingProfile.value=false;recharges.value=emptyPage();transactions.value=emptyPage();error.value='';success.value=''
  try{const value=await getPartner(id);if(active&&current===detailGeneration){detail.value=value;profile.value=profileFor(value.partner);transactionCurrency.value=query.currencyCode}}
  catch(e){if(active&&current===detailGeneration)error.value=message(e)}finally{if(active&&current===detailGeneration)detailLoading.value=false}
}
async function refreshDetail(){const id=detail.value?.partner.id,current=detailGeneration;if(!id)return;try{const value=await getPartner(id);if(active&&current===detailGeneration)detail.value=value}catch(e){if(active&&current===detailGeneration)error.value=message(e)}}
async function mutate<T>(name:string,payload:object,action:(key:string)=>Promise<T>,apply:(value:T)=>void,notice:string){
  if(busy.value||!active)return false
  const fingerprint=JSON.stringify(payload);let attempt=attempts.get(name)
  if(!attempt||attempt.fingerprint!==fingerprint){attempt={fingerprint,key:crypto.randomUUID()};attempts.set(name,attempt)}
  busy.value=true;error.value='';success.value=''
  try{const value=await action(attempt.key);if(!active)return false;attempts.delete(name);apply(value);success.value=notice;return true}catch(e){if(active)error.value=message(e);return false}finally{if(active)busy.value=false}
}
function openAccount(row?:PartnerSummary){accountPartner.value=row||null;account.value=blankAccount();accountOpen.value=true;error.value='';success.value=''}
function closeAccount(){account.value.password='';attempts.delete('partner:provision');accountOpen.value=false;accountPartner.value=null}
async function saveAccount(){
  const existing=accountPartner.value
  const payload=existing?{existingCustomerId:existing.id,userName:account.value.userName.trim(),nickName:account.value.nickName.trim(),password:account.value.password}:{...account.value,displayName:account.value.companyName.trim(),nickName:account.value.nickName.trim()||account.value.contactName.trim()}
  let createdId=0
  if(await mutate('partner:provision',payload,key=>provisionPartner({...payload,requestKey:key}),value=>{createdId=value.customerId;closeAccount()},existing?'子代理后台账号已开通。':'子代理已开通。')){await load();await openPartner(createdId);success.value=existing?'子代理后台账号已开通。':'子代理已开通。'}
}
async function saveProfile(){const id=detail.value?.partner.id;if(!id)return;const payload={...profile.value};if(await mutate(`partner:${id}:profile`,payload,()=>updatePartner(id,payload),value=>{if(detail.value)detail.value.partner=value;editingProfile.value=false},'子代理资料已保存。'))await load(listing.value.page)}
async function toggleOperator(operator:PartnerOperator){const id=detail.value?.partner.id;if(!id)return;const payload={sysUserId:operator.sysUserId,active:!operator.active};if(await mutate(`partner:${id}:operator:${operator.sysUserId}`,payload,()=>setPartnerOperatorState(id,operator.sysUserId,payload.active),()=>{},payload.active?'该账号的送评权限已启用，请重新登录。':'该账号的送评权限已停用。')){await refreshDetail();await load(listing.value.page)}}
async function loadFinance(){if(!financeVisible.value)return;await Promise.all([loadRecharges(),loadTransactions()])}
async function loadRecharges(page=1){const id=detail.value?.partner.id,current=financeGeneration;if(!id||!financeVisible.value)return;try{const value=await getWalletRecharges(id,{page,pageSize:20,status:rechargeStatus.value||undefined});if(active&&current===financeGeneration)recharges.value=value.data}catch(e){if(active&&current===financeGeneration)error.value=message(e)}}
async function loadTransactions(page=1){const id=detail.value?.partner.id,current=financeGeneration;if(!id||!financeVisible.value)return;try{const value=await getWalletTransactions(id,{page,pageSize:20,currencyCode:transactionCurrency.value});if(active&&current===financeGeneration)transactions.value=value.data}catch(e){if(active&&current===financeGeneration)error.value=message(e)}}
function startRecharge(){Object.assign(recharge,{currencyCode:query.currencyCode,amount:'',providerCode:'bank_transfer',payerReference:'',proofReference:''});rechargeOpen.value=true}
async function saveRecharge(){const id=detail.value?.partner.id;if(!id)return;const payload={...recharge};if(await mutate(`partner:${id}:recharge`,payload,key=>requestPartnerRecharge(id,{...payload,requestKey:key}),()=>{rechargeOpen.value=false},'充值申请已登记，待核实实际收款。')){await refreshDetail();await loadFinance();await load(listing.value.page)}}
function startReview(item:PartnerRecharge,approved:boolean){Object.assign(review,{item,approved,providerTransactionId:'',note:''});reviewOpen.value=true}
async function saveReview(){const id=detail.value?.partner.id,item=review.item;if(!id||!item)return;const payload={providerTransactionId:review.providerTransactionId.trim(),note:review.note.trim()};if(await mutate(`partner:${id}:review:${item.id}`,payload,()=>reviewWalletRecharge(id,item.id,review.approved,payload),()=>{reviewOpen.value=false},review.approved?'充值已核准并入账。':'充值已驳回。')){await refreshDetail();await loadFinance();await load(listing.value.page)}}
function workspace(row:PartnerSummary,tab='clients'){void router.push({path:'/nxr/submission-workbench',query:{company:String(row.id),tab}})}
onMounted(()=>load())
onBeforeUnmount(()=>{active=false;listGeneration++;detailGeneration++;financeGeneration++;account.value.password='';attempts.clear()})
</script>

<template>
  <main class="nxr-workspace partners-page" data-testid="partner-management">
    <NxrPageHeader :title="$t('nav.partnerManagement')" :summary="`共 ${listing.total} 家子代理`"><template #actions><el-button :loading="loading" :disabled="busy" @click="load(listing.page)">刷新</el-button><el-button v-if="canOpen" type="primary" :disabled="busy" data-testid="partner-open-create" @click="openAccount()">开通子代理</el-button></template></NxrPageHeader>
    <el-alert v-if="error" :title="error" type="error" :closable="false" class="partner-alert" /><el-alert v-if="success" :title="success" type="success" :closable="false" class="partner-alert" />
    <el-card shadow="never"><el-form inline @submit.prevent="load()"><el-form-item label="查找子代理"><el-input v-model="query.query" clearable placeholder="企业、联系人或账号" data-testid="partner-search" /></el-form-item><el-form-item label="状态"><el-select v-model="query.active" style="width:120px"><el-option label="全部" value="" /><el-option label="启用" :value="true" /><el-option label="停用" :value="false" /></el-select></el-form-item><el-form-item v-if="canFinance" label="余额币种"><el-select v-model="query.currencyCode" style="width:100px"><el-option v-for="code in currencies" :key="code" :value="code" :label="code" /></el-select></el-form-item><el-form-item><el-button type="primary" native-type="submit" :loading="loading">查询</el-button></el-form-item></el-form>
      <el-table v-loading="loading" :data="listing.items" row-key="id" border><el-table-column label="子代理企业" min-width="210"><template #default="{row}"><el-button link type="primary" :disabled="busy" :data-testid="`partner-detail-${row.id}`" @click="openPartner(row.id)">{{row.companyName||row.displayName}}</el-button><small>{{row.email}}</small></template></el-table-column><el-table-column label="联系人" min-width="140"><template #default="{row}">{{row.contactName}}<small>{{row.mobile||'—'}}</small></template></el-table-column><el-table-column label="后台账号" min-width="105"><template #default="{row}">{{row.activeOperatorCount}} / {{row.operatorCount}} 启用<small>{{row.operatorAccounts||'暂无后台账号'}}</small></template></el-table-column><el-table-column prop="clientCount" label="终端客户" width="95" /><el-table-column prop="inventoryCount" label="库存卡片" width="95" /><el-table-column prop="pendingBatchCount" label="进行中批次" width="110" /><el-table-column v-if="canFinance" :label="`${query.currencyCode} 余额`" min-width="145"><template #default="{row}">{{row.financeVisible&&row.walletBalance!==null?formatMoney(row.walletBalance,row.currencyCode):'—'}}</template></el-table-column><el-table-column v-if="canFinance" label="待核款" width="90"><template #default="{row}">{{row.pendingRechargeCount??'—'}}</template></el-table-column><el-table-column label="状态" width="85"><template #default="{row}"><el-tag :type="row.active?'success':'info'">{{row.active?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" min-width="165" fixed="right"><template #default="{row}"><el-button link type="primary" :disabled="busy" @click="openPartner(row.id)">管理</el-button><el-button v-if="canWorkbench&&row.active" link type="primary" :disabled="busy" @click="workspace(row)">送评工作台</el-button></template></el-table-column></el-table><el-pagination v-if="listing.total>listing.pageSize" class="partner-pagination" layout="prev,pager,next,total" :total="listing.total" :page-size="listing.pageSize" :current-page="listing.page" :disabled="loading||busy" @current-change="load" />
    </el-card>
    <el-drawer v-model="detailOpen" :title="detail?.partner.companyName||'子代理详情'" size="min(1120px,96vw)" :close-on-click-modal="!busy" :show-close="!busy" destroy-on-close>
      <div v-loading="detailLoading" data-testid="partner-detail"><el-alert v-if="error" :title="error" type="error" :closable="false" class="partner-alert" /><el-alert v-if="success" :title="success" type="success" :closable="false" class="partner-alert" /><template v-if="detail"><div class="partner-detail-heading"><div><el-tag :type="detail.partner.active?'success':'info'">{{detail.partner.active?'启用':'停用'}}</el-tag><span>{{detail.partner.contactName}} · {{detail.partner.mobile||detail.partner.email}}</span></div><el-button v-if="canWorkbench&&detail.partner.active" type="primary" :disabled="busy" @click="workspace(detail.partner)">查看送评工作台</el-button></div><div class="partner-stats"><article><strong>{{detail.partner.clientCount}}</strong><span>终端客户</span></article><article><strong>{{detail.partner.inventoryCount}}</strong><span>库存卡片</span></article><article><strong>{{detail.partner.pendingBatchCount}}</strong><span>进行中批次</span></article><article><strong>{{detail.partner.activeOperatorCount}}</strong><span>启用后台账号</span></article></div>
        <el-tabs v-model="detailTab" @tab-change="value=>{if(value==='wallet')loadFinance()}"><el-tab-pane label="企业资料与账号" name="overview"><div class="partner-section-heading"><h3>子代理资料</h3><el-button v-if="canManage&&!editingProfile" :disabled="busy" @click="profile=profileFor(detail.partner);editingProfile=true">编辑资料 / 启停</el-button></div><el-form v-if="editingProfile" label-position="top" :disabled="busy" @submit.prevent="saveProfile"><div class="partner-form-grid"><el-form-item label="子代理企业名称"><el-input v-model="profile.companyName" required maxlength="191" /></el-form-item><el-form-item label="账户显示名称"><el-input v-model="profile.displayName" required maxlength="128" /></el-form-item><el-form-item label="联系人"><el-input v-model="profile.contactName" required maxlength="128" /></el-form-item><el-form-item label="联系电话"><el-input v-model="profile.mobile" maxlength="64" /></el-form-item><el-form-item label="联系邮箱"><el-input v-model="profile.email" type="email" required maxlength="191" /></el-form-item><el-form-item label="状态"><el-switch v-model="profile.active" active-text="启用" inactive-text="停用" /></el-form-item></div><el-alert v-if="!profile.active" title="停用后，该子代理的后台账号将无法继续操作企业业务，历史记录保留。" type="warning" :closable="false" /><div class="partner-actions"><el-button @click="editingProfile=false">取消</el-button><el-button type="primary" native-type="submit" :loading="busy">保存资料</el-button></div></el-form><el-descriptions v-else :column="2" border><el-descriptions-item label="企业名称">{{detail.partner.companyName}}</el-descriptions-item><el-descriptions-item label="账户名称">{{detail.partner.displayName}}</el-descriptions-item><el-descriptions-item label="联系人">{{detail.partner.contactName}}</el-descriptions-item><el-descriptions-item label="联系电话">{{detail.partner.mobile||'—'}}</el-descriptions-item><el-descriptions-item label="邮箱">{{detail.partner.email}}</el-descriptions-item><el-descriptions-item label="开通时间">{{agentDateLabel(detail.partner.createdAt)}}</el-descriptions-item></el-descriptions><div class="partner-section-heading"><h3>后台账号</h3><el-button v-if="canOpen&&detail.partner.active" :disabled="busy" @click="openAccount(detail.partner)">新增后台账号</el-button></div><el-table :data="detail.operators" border><el-table-column prop="userName" label="登录账号" /><el-table-column prop="nickName" label="姓名" /><el-table-column label="送评权限状态"><template #default="{row}">{{!row.backendActive?'后台账号已停用':row.active?'已启用':'已停用'}}</template></el-table-column><el-table-column v-if="canManageOperators" label="操作" min-width="150"><template #default="{row}"><el-button link :type="row.active?'danger':'primary'" :disabled="busy||(!row.active&&!row.backendActive)" @click="toggleOperator(row)">{{row.active?'停用送评权限':'启用送评权限'}}</el-button></template></el-table-column></el-table></el-tab-pane>
          <el-tab-pane v-if="financeVisible" label="余额与核款" name="wallet"><div class="partner-section-heading"><h3>预充值余额</h3><el-button v-if="canRecharge&&detail.partner.active" type="primary" :disabled="busy" data-testid="partner-open-recharge" @click="startRecharge">登记线下充值</el-button></div><div class="partner-wallets"><article v-for="wallet in detail.wallets" :key="wallet.currencyCode"><span>{{wallet.currencyCode}}</span><strong>{{formatMoney(wallet.balance,wallet.currencyCode)}}</strong></article><p v-if="!detail.wallets.length">暂无余额记录。</p></div><div class="partner-section-heading"><h3>充值核款</h3><el-select v-model="rechargeStatus" style="width:140px" @change="loadRecharges()"><el-option label="待核款" value="pending" /><el-option label="全部记录" value="" /><el-option label="已到账" value="confirmed" /><el-option label="已驳回" value="rejected" /></el-select></div><el-table :data="recharges.items" border><el-table-column prop="rechargeNo" label="充值单" min-width="180" /><el-table-column label="金额" min-width="140"><template #default="{row}">{{formatMoney(row.amount,row.currencyCode)}}</template></el-table-column><el-table-column label="凭证" min-width="180"><template #default="{row}">{{row.payerReference}}<small>{{row.proofReference}}</small></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}">{{agentStatusLabel(row.statusCode)}}</template></el-table-column><el-table-column label="操作" min-width="140"><template #default="{row}"><template v-if="row.statusCode==='pending'"><el-button link type="success" :disabled="busy" @click="startReview(row,true)">确认到账</el-button><el-button link type="danger" :disabled="busy" @click="startReview(row,false)">驳回</el-button></template><span v-else>{{row.reviewNote||'—'}}</span></template></el-table-column></el-table><el-pagination v-if="recharges.total>20" class="partner-pagination" layout="prev,pager,next" :total="recharges.total" :page-size="20" :current-page="recharges.page" @current-change="loadRecharges" /><div class="partner-section-heading"><h3>余额流水</h3><el-select v-model="transactionCurrency" style="width:110px" @change="loadTransactions()"><el-option v-for="code in currencies" :key="code" :value="code" :label="code" /></el-select></div><el-table :data="transactions.items" border><el-table-column label="时间" min-width="160"><template #default="{row}">{{agentDateLabel(row.createdAt)}}</template></el-table-column><el-table-column label="金额" min-width="140"><template #default="{row}">{{row.directionCode==='debit'?'−':'+'}}{{formatMoney(row.amount,transactionCurrency)}}</template></el-table-column><el-table-column label="余额" min-width="140"><template #default="{row}">{{formatMoney(row.balanceAfter,transactionCurrency)}}</template></el-table-column><el-table-column prop="note" label="说明" min-width="160" /></el-table><el-pagination v-if="transactions.total>20" class="partner-pagination" layout="prev,pager,next" :total="transactions.total" :page-size="20" :current-page="transactions.page" @current-change="loadTransactions" /></el-tab-pane>
          <el-tab-pane label="来件与送评批次" name="batches"><div class="partner-actions"><el-button v-if="canWorkbench&&detail.partner.active" :disabled="busy" @click="workspace(detail.partner,'intakes')">查看客户来件与库存</el-button><el-button v-if="canWorkbench&&detail.partner.active" :disabled="busy" @click="workspace(detail.partner,'batches')">查看全部送评批次</el-button></div><h3>最近送评批次</h3><el-table :data="detail.batches.items" border><el-table-column prop="batchNo" label="批次号" min-width="210" /><el-table-column prop="batchName" label="批次名称" min-width="150" /><el-table-column label="状态" min-width="120"><template #default="{row}">{{agentStatusLabel(row.statusCode)}}</template></el-table-column><el-table-column prop="acceptedRows" label="客户订单" width="100" /><el-table-column label="时间" min-width="170"><template #default="{row}">{{agentDateLabel(row.createdAt)}}</template></el-table-column><el-table-column label="NXR 操作" min-width="180"><template #default="{row}"><el-button v-if="canNxrOrders" link type="primary" :disabled="busy" @click="router.push({path:'/nxr/orders',query:{batchId:String(row.id)}})">主包裹收货 / 查看物流</el-button></template></el-table-column></el-table></el-tab-pane>
        </el-tabs>
      </template></div>
    </el-drawer>
    <el-dialog v-model="accountOpen" :title="accountPartner?'新增子代理后台账号':'开通子代理'" width="min(740px,94vw)" :close-on-click-modal="false" :show-close="!busy" @closed="account.password=''" append-to-body><el-alert v-if="error" :title="error" type="error" :closable="false" class="partner-alert" /><p v-if="accountPartner">所属子代理：{{accountPartner.companyName}}</p><el-form label-position="top" :disabled="busy" @submit.prevent="saveAccount"><div v-if="!accountPartner" class="partner-form-grid"><el-form-item label="子代理企业名称" required><el-input v-model="account.companyName" required maxlength="191" data-testid="partner-company-name" /></el-form-item><el-form-item label="联系人" required><el-input v-model="account.contactName" required maxlength="128" /></el-form-item><el-form-item label="联系邮箱" required><el-input v-model="account.email" type="email" required maxlength="191" /></el-form-item><el-form-item label="联系电话"><el-input v-model="account.mobile" maxlength="64" /></el-form-item></div><el-divider>后台登录账号</el-divider><div class="partner-form-grid"><el-form-item label="登录账号" required><el-input v-model="account.userName" required maxlength="30" autocomplete="off" data-testid="partner-user-name" /></el-form-item><el-form-item label="账号姓名"><el-input v-model="account.nickName" maxlength="30" /></el-form-item><el-form-item label="初始密码（5–20 位）" required><el-input v-model="account.password" type="password" required minlength="5" maxlength="20" autocomplete="new-password" data-testid="partner-initial-password" /></el-form-item></div><div class="partner-actions"><el-button :disabled="busy" @click="closeAccount">取消</el-button><el-button type="primary" native-type="submit" :loading="busy" data-testid="partner-save-provision">{{accountPartner?'开通后台账号':'确认开通子代理'}}</el-button></div></el-form></el-dialog>
